<?php
declare(strict_types=1);
require_once __DIR__.'/sales.php';
require_once __DIR__.'/quote-ai.php';
// Tous les calculs monétaires utilisent des unités entières : millimes TND, centimes EUR.
function businessDay(): string {return (new DateTimeImmutable('now',new DateTimeZone(cfg()['business_timezone']??'Africa/Tunis')))->format('Y-m-d');}
function moneyUnits(mixed $value,string $currency): int {
 if(!in_array($currency,['TND','EUR','USD'],true))out(['error'=>'Devise invalide'],422);
 if(!(is_string($value)||is_int($value)||is_float($value))||!preg_match('/^(\d{1,12})(?:\.(\d{1,3}))?$/D',(string)$value,$m))out(['error'=>'Montant invalide'],422);
 $digits=$currency==='TND'?3:2;$dec=$m[2]??'';if(strlen($dec)>$digits&&trim(substr($dec,$digits),'0')!=='')out(['error'=>'Précision maximale : trois décimales en TND, deux en EUR ou USD.'],422);
 return (int)$m[1]*(10**$digits)+(int)str_pad(substr($dec,0,$digits),$digits,'0');
}
function amountString(int $value,string $currency): string {$digits=$currency==='TND'?3:2;$scale=10**$digits;return intdiv($value,$scale).'.'.str_pad((string)($value%$scale),$digits,'0',STR_PAD_LEFT);}
function percentBps(mixed $value): int {if(!(is_string($value)||is_int($value)||is_float($value)))out(['error'=>'Pourcentage invalide'],422);$s=(string)$value;if(!preg_match('/^(\d{1,3})(?:\.(\d{1,2}))?$/D',$s,$m))out(['error'=>'Pourcentage invalide'],422);$n=(int)$m[1]*100+(int)str_pad($m[2]??'',2,'0');if($n>10000)out(['error'=>'Pourcentage supérieur à 100'],422);return $n;}
function productFor(array $u,int $id): array {$p=run('SELECT * FROM wm_products WHERE id=? AND org_id=?',[$id,$u['org_id']])->fetch();if(!$p)out(['error'=>'Produit introuvable'],404);return $p;}
function opportunityFor(array $u,int $id): array {$o=run('SELECT * FROM wm_opportunities WHERE id=? AND org_id=?',[$id,$u['org_id']])->fetch();if(!$o)out(['error'=>'Opportunité introuvable'],404);return $o;}
function quoteFor(array $u,int $id): array {$q=run('SELECT * FROM wm_quotes WHERE id=? AND org_id=?',[$id,$u['org_id']])->fetch();if(!$q)out(['error'=>'Devis introuvable'],404);$q['items']=run('SELECT * FROM wm_quote_items WHERE quote_id=? AND org_id=? ORDER BY position',[$id,$u['org_id']])->fetchAll();$q['client']=lead($u,(int)$q['lead_id']);$q['costing']=quoteCostFor($u,$q);$q['expired']=$q['status']==='issued'&&$q['valid_until']<businessDay();return $q;}
function companyFor(array $u): array {return run('SELECT * FROM wm_company_profiles WHERE org_id=?',[$u['org_id']])->fetch()?:['legal_name'=>$u['organization'],'address'=>'','registration_id'=>'','email'=>$u['email'],'phone'=>'','payment_terms'=>'','footer'=>'','version'=>0];}
function quoteCalculation(array $u,mixed $items,string $currency): array {
 if(!is_array($items)||!array_is_list($items)||count($items)<1||count($items)>50)out(['error'=>'Un devis doit contenir entre 1 et 50 lignes.'],422);
 $sums=['subtotal'=>0,'total_discount'=>0,'total_tax'=>0,'total'=>0];$out=[];
 foreach($items as $i=>$item){if(!is_array($item))out(['error'=>'Ligne invalide'],422);$p=null;$productId=$item['product_id']??null;$productId=$productId===null||$productId===''?null:num($productId,1);if($productId)$p=productFor($u,$productId);
  $label=text($item['label']??$p['name']??'',500,true);$unit=text($item['unit']??$p['unit']??'pièce',30,true);$qValue=$item['quantity']??'1';if(!(is_string($qValue)||is_int($qValue)||is_float($qValue)))out(['error'=>'Quantité invalide'],422);$quantity=(string)$qValue;if(!preg_match('/^(\d{1,5})(?:\.(\d{1,3}))?$/D',$quantity,$qm))out(['error'=>'Quantité invalide (maximum 99 999,999)'],422);$qty=(int)$qm[1]*1000+(int)str_pad($qm[2]??'',3,'0');if($qty<=0)out(['error'=>'Quantité strictement positive requise'],422);
  $price=moneyUnits($item['unit_price']??'', $currency);if($price>999999999)out(['error'=>'Prix unitaire trop élevé'],422);$discount=percentBps($item['discount']??0);if(!array_key_exists('vat',$item)||$item['vat']==='')out(['error'=>'Renseignez explicitement la TVA de chaque ligne (0 si applicable).'],422);$vat=percentBps($item['vat']??0);
  $gross=intdiv($price*$qty+500,1000);$discountAmount=intdiv($gross*$discount+5000,10000);$net=$gross-$discountAmount;$tax=intdiv($net*$vat+5000,10000);$total=$net+$tax;
  $sums['subtotal']+=$net;$sums['total_discount']+=$discountAmount;$sums['total_tax']+=$tax;$sums['total']+=$total;
  if($sums['total']>99999999999999)out(['error'=>'Montant total trop élevé'],422);
  $out[]=['product_id'=>$productId,'sku'=>text($item['sku']??$p['sku']??'',60),'label'=>$label,'unit'=>$unit,'quantity'=>number_format($qty/1000,3,'.',''),'unit_price'=>amountString($price,$currency),'discount_bps'=>$discount,'vat_bps'=>$vat,'gross'=>amountString($gross,$currency),'discount_amount'=>amountString($discountAmount,$currency),'net'=>amountString($net,$currency),'tax'=>amountString($tax,$currency),'total'=>amountString($total,$currency)];
 }foreach($sums as &$v)$v=amountString($v,$currency);unset($v);return ['items'=>$out,'totals'=>$sums];
}
function saveQuote(array $u,array $b,?int $id=null): array {
 $leadId=num($b['lead_id']??0,1);$l=lead($u,$leadId);$currency=text($b['currency']??$l['currency'],3);if($currency!==$l['currency'])out(['error'=>'La devise doit correspondre au marché du prospect : '.$l['currency']],422);
 $op=$b['opportunity_id']??null;$op=$op===null||$op===''?null:num($op,1);if($op){$o=opportunityFor($u,$op);if((int)$o['lead_id']!==$leadId||$o['currency']!==$currency)out(['error'=>'Opportunité et prospect/devise incohérents'],422);}
 $title=text($b['title']??'',200,true);$address=text($b['customer_address']??'',2000);$valid=dateValue($b['valid_until']??'',false);$notes=text($b['notes']??'',4000);$calculation=quoteCalculation($u,$b['items']??[],$currency);$t=$calculation['totals'];$costValues=array_key_exists('costs',$b)?quoteCostValues($b['costs'],$currency):null;
 db()->beginTransaction();if($id){$q=run('SELECT * FROM wm_quotes WHERE id=? AND org_id=? FOR UPDATE',[$id,$u['org_id']])->fetch();if(!$q){db()->rollBack();out(['error'=>'Devis introuvable'],404);}if($q['status']!=='draft'||(int)$q['version']!==num($b['version']??0,1)){db()->rollBack();out(['error'=>'Devis émis ou modifié. Rechargez-le ; un devis émis est figé.'],409);}run('UPDATE wm_quotes SET lead_id=?,opportunity_id=?,currency=?,title=?,customer_address=?,valid_until=?,notes=?,subtotal=?,total_discount=?,total_tax=?,total=?,version=version+1 WHERE id=? AND org_id=?',[$leadId,$op,$currency,$title,$address,$valid,$notes,$t['subtotal'],$t['total_discount'],$t['total_tax'],$t['total'],$id,$u['org_id']]);run('DELETE FROM wm_quote_items WHERE quote_id=? AND org_id=?',[$id,$u['org_id']]);}
 else{run('INSERT INTO wm_quotes(org_id,lead_id,opportunity_id,currency,title,customer_address,valid_until,notes,subtotal,total_discount,total_tax,total,created_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)',[$u['org_id'],$leadId,$op,$currency,$title,$address,$valid,$notes,$t['subtotal'],$t['total_discount'],$t['total_tax'],$t['total'],$u['id']]);$id=(int)db()->lastInsertId();}
 foreach($calculation['items'] as $index=>$item)run('INSERT INTO wm_quote_items(org_id,quote_id,position,product_id,sku,label,unit,quantity,unit_price,discount_bps,vat_bps,gross,discount_amount,net,tax,total) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)',array_merge([$u['org_id'],$id,$index+1],array_values($item)));
 if($costValues!==null)quoteCostSave($u,$id,$currency,$b['costs'],$costValues);
 audit($u,'quote.draft_saved',$id);db()->commit();return quoteFor($u,$id);
}
function issueQuote(array $u,int $id,int $version): array {
 db()->beginTransaction();$q=run('SELECT * FROM wm_quotes WHERE id=? AND org_id=? FOR UPDATE',[$id,$u['org_id']])->fetch();if(!$q){db()->rollBack();out(['error'=>'Devis introuvable'],404);}if($q['status']!=='draft'){db()->commit();return quoteFor($u,$id);}if((int)$q['version']!==$version){db()->rollBack();out(['error'=>'Brouillon modifié. Rechargez-le avant émission.'],409);}
 $cost=quoteCostFor($u,$q);if($cost&&$cost['stale']){db()->rollBack();out(['error'=>'Les lignes ont changé : relisez et enregistrez les coûts avant émission.'],409);}
 $seller=companyFor($u);if(trim($seller['address'])===''||trim($seller['legal_name'])===''||trim($seller['email'])===''){db()->rollBack();out(['error'=>'Complétez les coordonnées émetteur dans Catalogue et devis avant émission.'],409);}if(trim($q['customer_address'])===''||$q['valid_until']<businessDay()){db()->rollBack();out(['error'=>'Adresse client et date de validité future ou du jour requises.'],422);}
 $l=lead($u,(int)$q['lead_id']);if($q['currency']!==$l['currency']){db()->rollBack();out(['error'=>'Le marché du prospect a changé. Révisez la devise du brouillon avant émission.'],409);}$year=(int)substr(businessDay(),0,4);run('INSERT INTO wm_quote_counters(org_id,quote_year,`last_value`) VALUES(?,?,0) ON DUPLICATE KEY UPDATE `last_value`=`last_value`',[$u['org_id'],$year]);$value=(int)run('SELECT `last_value` FROM wm_quote_counters WHERE org_id=? AND quote_year=? FOR UPDATE',[$u['org_id'],$year])->fetchColumn()+1;run('UPDATE wm_quote_counters SET `last_value`=? WHERE org_id=? AND quote_year=?',[$value,$u['org_id'],$year]);$number='DEV-'.$year.'-'.str_pad((string)$value,6,'0',STR_PAD_LEFT);
 $customer=['document_date'=>businessDay(),'name'=>$l['name'],'address'=>$q['customer_address'],'email'=>$l['email'],'phone'=>$l['phone'],'country'=>$l['country']];
 run('UPDATE wm_quotes SET number=?,status=?,seller_snapshot=?,customer_snapshot=?,issued_at=UTC_TIMESTAMP(),version=version+1 WHERE id=? AND org_id=?',[$number,'issued',json_encode($seller,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR),json_encode($customer,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR),$id,$u['org_id']]);audit($u,'quote.issued',$id);db()->commit();return quoteFor($u,$id);
}
